export const BIRTH_LOCATIONS:BirthLocation[]=points.map(([name,longitude])=>({id:name,name,longitude,source:LOCATION_SOURCE}));
/** Factual coordinate quoted from Dongtai government's published environmental report.
 * PDF physical page 9 (printed p.6), table 1-9: 富安镇政府 120.478263 / 32.674981.
 * This is the town-government representative point, never Dongtai county centre.
 * Full provenance and reuse boundary: LOCATIONS.md. */
export const FUAN_LOCATION:BirthLocation={id:'江苏省/盐城市/东台市/富安镇',name:'江苏省/盐城市/东台市/富安镇',longitude:120.478263,source:'dongtai.gov.cn-huaduo-eia-202303-p6-fuan-government'};
/** Only these locations can be newly selected. Legacy nationwide inputs remain valid. */
export const SELECTABLE_BIRTH_LOCATIONS:readonly BirthLocation[]=[...BIRTH_LOCATIONS.filter(l=>l.name.startsWith('江苏省/')),FUAN_LOCATION];
const compactAddress=(value:string)=>value.replace(/[\s/／、,，·>＞-]+/g,'');
export function searchBirthLocations(query:string):BirthLocation[]{
 const terms=query.trim().split(/\s+/).map(compactAddress).filter(Boolean);
 return terms.length?SELECTABLE_BIRTH_LOCATIONS.filter(l=>terms.every(t=>compactAddress(l.name).includes(t))).slice(0,60):[];
}
export function birthLocationNote(location:BirthLocation):string {
 if(location.id===FUAN_LOCATION.id&&location.source===FUAN_LOCATION.source)return '富安镇政府代表点，非具体出生建筑';
 return location.name.startsWith('江苏省/')?'历史市县代表点，非具体出生建筑':'历史已保存地点；新选择仅支持江苏省';
}
